- name: Retain UI-test Settings export control-flow trace
  if: ${{ matrix.suite == 'account-cooking' && always() }}
  run: |
    if [ -f settings-about-145.log ]; then
      xcrun simctl spawn "$SIM_ID" log show --style compact --last 30m \
        --predicate 'subsystem == "com.melusik.ate" AND category == "settings-export-diagnostic"' \
        > settings-export-diagnostic.log 2>&1 || {
          echo "::warning::Settings export trace collection failed; inspect settings-export-diagnostic.log"
        }
    fi

import OSLog
                            exportDiagnostic("action-entered")
                            guard !exporting else {
                                exportDiagnostic("already-exporting-refused")
                                return
                            }
                            guard !exporting else { return }
                                        exportDiagnostic("temporary-file-failed")
                                    exportDiagnostic("share-state-set")
                                    exportDiagnostic("capture-failed")
    /// Trace control flow only. Never log exported bytes, file URLs or account data.
    /// No UI, retries, waits or alternate export route are introduced.
    private func exportDiagnostic(_ event: String) {
        guard AppConfig.isUITesting else { return }
        Logger(subsystem: "com.melusik.ate", category: "settings-export-diagnostic")
            .notice("event=\(event, privacy: .public) uptime=\(ProcessInfo.processInfo.systemUptime, privacy: .public)")
    }

let initialReadyResult = XCTWaiter.wait(for: [XCTNSPredicateExpectation(predicate: ready, object: refresh)], timeout: 10)
if initialReadyResult != .completed {
    refreshDiagnostics("pre-refresh-ready-failure", refresh: refresh, status: status)
}
XCTAssertEqual(initialReadyResult, .completed)
XCTAssertEqual(XCTWaiter.wait(for: [XCTNSPredicateExpectation(predicate: ready, object: refresh)], timeout: 10), .completed)
